func ttPut(t *strings.Builder, txt *port.Cells, s int32, n int32) int32 {
	// A run of `txt` as ASCII text: a code point past 126 (or a control) is `{N}`, its number.
	var i int32 = 0
	var c int32 = 0
	if s < 0 {
		port.TextAscii(t, "-")
		return 0
	}
	for i < n {
		c = port.CellsAt(txt, s+i)
		if (c >= 32) && (c <= 126) {
			port.TextCp(t, c)
		} else {
			port.TextAscii(t, "{")
			port.TextI32(t, c)
			port.TextAscii(t, "}")
		}
		i += 1
	}
	return 0
}

func ttRole(t *strings.Builder, se *port.Cells, row int32) int32 {
	// The standard type of element `row` as its name (`H2` for an Hn), `?` for none.
	var at int32 = row * 64
	if port.CellsAt(se, at+5) == 0 {
		port.TextAscii(t, "?")
		return 0
	}
	if port.CellsAt(se, at+5) == 17 {
		port.TextAscii(t, "H")
		port.TextI32(t, port.CellsAt(se, at+7))
		return 0
	}
	pdfsnames.SrEmitName(t, port.CellsAt(se, at+5))
	return 0
}

