func ttNl(b []byte, i int32) int32 {
	var k int32 = i
	for (k < port.BlobLen(b)) && (port.BlobU8(b, k) != 10) {
		k += 1
	}
	return k
}

func ttTab(b []byte, i int32, lim int32) int32 {
	var k int32 = i
	for (k < lim) && (port.BlobU8(b, k) != 9) {
		k += 1
	}
	return k
}

func ttDump(pdf *port.Src, t *strings.Builder) int32 {
	var res *port.Cells = port.NewCells()
	return ttLine(pdf, 0, t, res)
}

func TestEveryFixtureDumpIsItsGolden(emonT *testing.T) {
	// Row: file, golden. The dump of the file, read in memory, is the golden's bytes (less its line feed):
	// every element with its role and how it was found, its kids, attributes and text properties, every
	// marked-content reference with the span it joined, the artifact spans, and the score, on all four targets.
	var f []byte = port.TestFile("pdf/tagged.txt")
	var n int32 = port.BlobLen(f)
	var pos int32 = 0
	var line int32 = 0
	var rows int32 = 0
	var e int32 = 0
	var s0 int32 = 0
	for pos < n {
		line += 1
		e = ttNl(f, pos)
		if (pos < e) && (port.BlobU8(f, pos) != 35) {
			rows += 1
			s0 = ttTab(f, pos, e)
			var t *strings.Builder = port.NewText()
			var g []byte = port.TestFileSpan(f, s0+1, e)
			port.AssertEqAt(emonT, ttDump(port.SrcOfBlob(port.TestFileSpan(f, pos, s0)), t), 0, "opened and read", line)
			port.AssertTextSpan(emonT, t, g, 0, port.BlobLen(g)-1, "the golden", line)
		}
		pos = e + 1
	}
	port.AssertThat(emonT, rows >= 10, "the fixtures were read")
}

func ttSay(pdf []byte, which int32, t *strings.Builder) int32 {
	var res *port.Cells = port.NewCells()
	return ttLine(port.SrcOfBlob(pdf), which, t, res)
}

func ttScore(pdf []byte) int32 {
	// The score of a file, -1 when it did not read.
	var res *port.Cells = port.NewCells()
	var t *strings.Builder = port.NewText()
	if ttLine(port.SrcOfBlob(pdf), 7, t, res) != 0 {
		return -1
	}
	return port.CellsAt(res, 0)
}

func TestTheCorrectDocumentSaysWhatItWasBuiltToSay(emonT *testing.T) {
	// good.pdf: Document > H1 (a custom `Heading` the RoleMap makes H1), Body (custom, P), four Sect with an H2
	// each, a list of three items with Lbl and LBody and ListNumbering Decimal, a ruled table of three rows with
	// TH cells whose Scope comes through a class, a Figure with Alt, a Caption, a Span with ActualText and E, a French
	// paragraph. Header, footer, watermark and the rules are artifacts of the right Type and Subtype.
	var pdf []byte = port.TestFile("pdf/tagged/good.pdf")
	var t1 *strings.Builder = port.NewText()
	var t2 *strings.Builder = port.NewText()
	var t3 *strings.Builder = port.NewText()
	var t4 *strings.Builder = port.NewText()
	var t5 *strings.Builder = port.NewText()
	var t6 *strings.Builder = port.NewText()
	port.AssertEq(emonT, ttSay(pdf, 1, t1), 0, "read")
	port.AssertText(emonT, t1, "Document:0 H1:1 P:1 Sect:0 H2:0 P:0 Sect:0 H2:0 L:0 LI:0 Lbl:0 LBody:0 LI:0 Lbl:0 LBody:0 LI:0 Lbl:0 LBody:0 Sect:0 H2:0 Table:0 TR:0 TH:0 TH:0 TH:0 TR:0 TD:0 TD:0 TD:0 TR:0 TD:0 TD:0 TD:0 Sect:0 H2:0 P:0 Span:0 Span:0 Figure:0 Caption:0 P:0", "roles and how")
	port.AssertEq(emonT, ttSay(pdf, 2, t2), 0, "read")
	port.AssertText(emonT, t2, "1: lang=en-US from=1 | 37: actual=third quarter exp=Quarter three from=1 | 39: alt=Bar chart of revenue by month from=1 | 41: lang=fr-FR from=41", "text properties")
	port.AssertEq(emonT, ttSay(pdf, 3, t3), 0, "read")
	port.AssertText(emonT, t3, "L items=3 labelled=3 agree=3 differ=0 numbering=Decimal kind=2 | Table rows=3 cols=3 regular=1 summary=Revenue and growth by region | TH scope=2 rowspan=-1 colspan=-1 headers=- | TH scope=2 rowspan=-1 colspan=-1 headers=- | TH scope=2 rowspan=-1 colspan=-1 headers=-", "tables and lists")
	port.AssertEq(emonT, ttSay(pdf, 4, t4), 0, "read")
	port.AssertText(emonT, t4, "28 0 0 | 594 545 49 0 0 | 2 28 0 0 | 42 28 0", "the join: every reference joined, 545 glyphs owned by an element and 49 in artifacts, the ParentTree agrees 28 times")
	port.AssertEq(emonT, ttSay(pdf, 5, t5), 0, "read")
	port.AssertText(emonT, t5, "1.1@2:1(16) 1.3@1:1(5) 3.0@0:0(0) 1.2@3:1(6) 1.1@2:1(16) 1.2@3:1(6)", "artifacts: a header at the top, a turned watermark, the rules (no text), a footer at the bottom, again")
	port.AssertEq(emonT, ttSay(pdf, 6, t6), 0, "read")
	port.AssertText(emonT, t6, "1000 1000 1000 1000 1000 1000 1000 1000", "the score: every component and the whole")
}

func TestTheTwinsSayWhatTheyWereBuiltToSay(emonT *testing.T) {
	// Each twin keeps the page and changes what the file says about it. bad.pdf: P under the Document for every
	// block, headings with the wrong levels, a running header tagged P, a section heading marked as a Footer and a
	// paragraph as Pagination. bad-allp: only the P. bad-levels: the tree with H6 H3 H1 H4 H2. bad-artifacts: only
	// the artifacts. bad-order: every list of kids reversed.
	var ta *strings.Builder = port.NewText()
	var tb *strings.Builder = port.NewText()
	var tc *strings.Builder = port.NewText()
	var td *strings.Builder = port.NewText()
	var te *strings.Builder = port.NewText()
	var tf *strings.Builder = port.NewText()
	var tg *strings.Builder = port.NewText()
	var th *strings.Builder = port.NewText()
	port.AssertEq(emonT, ttSay(port.TestFile("pdf/tagged/bad.pdf"), 5, ta), 0, "read bad")
	port.AssertText(emonT, ta, "1.2@1:2(10) 1.0@1:2(96) 3.0@0:0(0)", "bad: a heading marked Footer and a paragraph marked Pagination, both in the body")
	port.AssertEq(emonT, ttSay(port.TestFile("pdf/tagged/bad.pdf"), 6, tb), 0, "read bad")
	port.AssertText(emonT, tb, "1000 500 1000 900 332 0 -1 113", "bad: score")
	port.AssertEq(emonT, ttSay(port.TestFile("pdf/tagged/bad-allp.pdf"), 1, tc), 0, "read allp")
	port.AssertText(emonT, tc, "Document:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0 P:0", "all P")
	port.AssertEq(emonT, ttSay(port.TestFile("pdf/tagged/bad-allp.pdf"), 6, td), 0, "read allp")
	port.AssertText(emonT, td, "1000 0 1000 0 -1 1000 -1 63", "all P: nothing but paragraphs, and the big text is not in a heading")
	port.AssertEq(emonT, ttSay(port.TestFile("pdf/tagged/bad-levels.pdf"), 6, te), 0, "read levels")
	port.AssertText(emonT, te, "1000 1000 1000 1000 500 1000 1000 656", "wrong levels: only the level component falls")
	port.AssertEq(emonT, ttSay(port.TestFile("pdf/tagged/bad-artifacts.pdf"), 6, tf), 0, "read artifacts")
	port.AssertText(emonT, tf, "1000 1000 1000 900 1000 0 1000 134", "mis-marked artifacts: only the artifact component falls")
	port.AssertEq(emonT, ttSay(port.TestFile("pdf/tagged/bad-order.pdf"), 6, tg), 0, "read order")
	port.AssertText(emonT, tg, "1000 1000 120 1000 1000 1000 1000 273", "reversed: the reading order falls to chance")
	port.AssertEq(emonT, ttSay(port.TestFile("pdf/tagged/bad-order.pdf"), 4, th), 0, "read order")
	port.AssertText(emonT, th, "28 0 0 | 594 545 49 0 0 | 2 28 0 0 | 42 28 0", "reversed: the join is the same")
}

func TestTheScoreSeparatesACorrectTreeFromMisTaggedTwins(emonT *testing.T) {
	// D076: the informativeness score must separate them clearly: the correct tree is above 950, the three
	// failures together are below 150, and each failure alone is below 700.
	var good int32 = ttScore(port.TestFile("pdf/tagged/good.pdf"))
	var bad int32 = ttScore(port.TestFile("pdf/tagged/bad.pdf"))
	var allp int32 = ttScore(port.TestFile("pdf/tagged/bad-allp.pdf"))
	var levels int32 = ttScore(port.TestFile("pdf/tagged/bad-levels.pdf"))
	var arts int32 = ttScore(port.TestFile("pdf/tagged/bad-artifacts.pdf"))
	var order int32 = ttScore(port.TestFile("pdf/tagged/bad-order.pdf"))
	port.AssertThat(emonT, good >= 950, "good")
	port.AssertThat(emonT, bad <= 150, "all three failures")
	port.AssertThat(emonT, allp <= 150, "everything P")
	port.AssertThat(emonT, levels <= 700, "wrong heading levels")
	port.AssertThat(emonT, arts <= 150, "artifacts mis-marked")
	port.AssertThat(emonT, order <= 300, "reading order reversed")
	port.AssertThat(emonT, (good-bad) > 800, "the gap between good and bad")
}

func TestTheOddTreeIsReadWholeAndWithoutAFault(emonT *testing.T) {
	// odd.pdf: a RoleMap loop (`?:3`), a custom role nobody mapped (`?:2`), P remapped to Span and Quote to
	// itself (`P:5`, `Quote:5`: used as they are), Heading -> H2 (`H2:1`), H7, Para -> P (`P:1`), and 70 nested Div cut at
	// the depth limit; an element reached twice is read once; the MCID claimed twice is a duplicate, the one nobody
	// claims and the stray text are not covered; the form's MCIDs join through /Stm; the Link is an object reference.
	var pdf []byte = port.TestFile("pdf/tagged/odd.pdf")
	var t1 *strings.Builder = port.NewText()
	var t2 *strings.Builder = port.NewText()
	var t3 *strings.Builder = port.NewText()
	var t4 *strings.Builder = port.NewText()
	var t5 *strings.Builder = port.NewText()
	port.AssertEq(emonT, ttSay(pdf, 8, t1), 0, "read")
	port.AssertText(emonT, t1, "Document:0 P:5 H2:1 Span:0 P:5 ?:3 ?:2 H7:0 P:1 Table:0 TR:0 TH:0 TD:0 TD:0 L:0 LI:0 Lbl:0 LBody:0 Quote:5", "roles and how")
	port.AssertEq(emonT, ttSay(pdf, 2, t2), 0, "read")
	port.AssertText(emonT, t2, "1: lang=de-DE from=1 | 9: alt=alternative actual=AB exp=expansion lang=fr id=id27 title=title from=9", "text properties: UTF-16 ActualText, an own /Lang")
	port.AssertEq(emonT, ttSay(pdf, 3, t3), 0, "read")
	port.AssertText(emonT, t3, "Table rows=1 cols=6 regular=1 summary=a table | TH scope=1 rowspan=2 colspan=2 headers=a b | TD scope=0 rowspan=3 colspan=-1 headers=- | TD scope=2 rowspan=-1 colspan=3 headers=- | L items=1 labelled=1 agree=0 differ=0 numbering=Disc kind=0", "attributes through /A, an array of /A, /C, a ClassMap array")
	port.AssertEq(emonT, ttSay(pdf, 4, t4), 0, "read")
	port.AssertText(emonT, t4, "8 2 1 | 55 44 6 5 0 | 3 6 1 3 | 82 10 1", "the join: 8 joined (two through /Stm), 2 not, a duplicate claim; ParentTree 3 keys, 6 agree, 1 differs, 3 absent")
	port.AssertEq(emonT, ttSay(pdf, 6, t5), 0, "read")
	port.AssertText(emonT, t5, "909 750 666 1000 -1 1000 1000 715", "the score")
}

func TestTheChromeTaggedDocumentsSayWhatChromeWrote(emonT *testing.T) {
	// The three Chrome-tagged synthetic documents: a table, lists, inverted headings. A correct table scores 1000;
	// the heading document, whose heading sizes were inverted on purpose, scores lower on levels.
	port.AssertEq(emonT, ttScore(port.TestFile("corpus/synth/pdf-tagged/table-simple-ruled.pdf")), 1000, "table")
	port.AssertEq(emonT, ttScore(port.TestFile("corpus/synth/pdf-tagged/lists-basic.pdf")), 937, "lists")
	port.AssertEq(emonT, ttScore(port.TestFile("corpus/synth/pdf-tagged/h-inverted.pdf")), 695, "inverted headings")
	var t *strings.Builder = port.NewText()
	port.AssertEq(emonT, ttSay(port.TestFile("corpus/synth/pdf-tagged/table-simple-ruled.pdf"), 9, t), 0, "read")
	port.AssertText(emonT, t, "Table rows=7 cols=5 regular=1 summary=-", "the table")
}

func ttSurvive(pdf *port.Src) int32 {
	var t *strings.Builder = port.NewText()
	return ttDump(pdf, t)
}

func ttCut(f []byte, n int32, cut *port.Cells) int32 {
	var i int32 = 0
	port.CellsDrop(cut, 0)
	for i < n {
		port.CellsPush(cut, port.BlobU8(f, i))
		i += 1
	}
	return n
}

func ttTruncations(f []byte, step int32, cut *port.Cells) int32 {
	// Every truncation of f, every `step` bytes: none may fault. Answers how many still read.
	var n int32 = port.BlobLen(f)
	var k int32 = 0
	var ok int32 = 0
	for k <= n {
		ttCut(f, k, cut)
		if ttSurvive(port.SrcOfBlob(port.CellsBlob(cut))) == 0 {
			ok += 1
		}
		k += step
	}
	return ok
}

func ttCorruptions(f []byte, rounds int32, flips int32, seed int32, cut *port.Cells, rng *port.Cells) int32 {
	// `rounds` copies of f with `flips` random bytes replaced (SplitMix, so every target damages the same bytes):
	// none may fault. Answers how many still read.
	var n int32 = port.BlobLen(f)
	var r int32 = 0
	var j int32 = 0
	var at int32 = 0
	var ok int32 = 0
	splitmix.SmSeed(rng, int64(seed))
	for r < rounds {
		ttCut(f, n, cut)
		j = 0
		for j < flips {
			at = splitmix.SmBelow(rng, n)
			port.CellsSet(cut, at, splitmix.SmBelow(rng, 256))
			j += 1
		}
		if ttSurvive(port.SrcOfBlob(port.CellsBlob(cut))) == 0 {
			ok += 1
		}
		r += 1
	}
	return ok
}

func TestNoTruncationOfAFixtureFaults(emonT *testing.T) {
	// Every 97th cut of each tagged fixture (a tree cut anywhere): nothing faults.
	var cut *port.Cells = port.NewCells()
	port.AssertThat(emonT, ttTruncations(port.TestFile("pdf/tagged/good.pdf"), 97, cut) >= 1, "good")
	port.AssertThat(emonT, ttTruncations(port.TestFile("pdf/tagged/bad-artifacts.pdf"), 97, cut) >= 1, "bad-artifacts")
	port.AssertThat(emonT, ttTruncations(port.TestFile("pdf/tagged/odd.pdf"), 61, cut) >= 1, "odd")
}

func TestNoCorruptionOfAFixtureFaults(emonT *testing.T) {
	// Copies with three bytes replaced: a wrong /K, /P, /Pg, /MCID, /S, /Nums, a broken RoleMap; none faults.
	var cut *port.Cells = port.NewCells()
	var rng *port.Cells = port.NewCells()
	port.AssertThat(emonT, ttCorruptions(port.TestFile("pdf/tagged/good.pdf"), 120, 3, 1, cut, rng) >= 0, "good")
	port.AssertThat(emonT, ttCorruptions(port.TestFile("pdf/tagged/odd.pdf"), 120, 3, 2, cut, rng) >= 0, "odd")
	port.AssertThat(emonT, ttCorruptions(port.TestFile("pdf/tagged/bad-order.pdf"), 120, 4, 3, cut, rng) >= 0, "bad-order")
}

func ttAsync(bytes []byte, chunk int32, t *strings.Builder) int32 {
	// Read `bytes` through an async source of `chunk`-byte chunks, re-running until an attempt does not miss; the dump
	// of that attempt goes to t. Answers that attempt's verdict, or -2 after 40 rounds.
	var base *port.Src = port.SrcChunked(bytes, chunk, 0)
	var round int32 = 0
	var more int32 = 1
	var verdict int32 = 0
	for more == 1 {
		var v *port.Src = port.SrcView(base)
		verdict = ttDump(v, t)
		if pdfsrc.PsMissed(v) {
			port.SrcCtl(base, 0, round)
			round += 1
			if round > 40 {
				more = 0
				verdict = -2
			}
		} else {
			more = 0
		}
	}
	return verdict
}

func TestFixturesThroughAnAsyncSourceAreTheirGoldenBytes(emonT *testing.T) {
	// D075: a missed attempt answers -1 and writes nothing; the host fetches what was missed and re-runs on a fresh
	// view. The correct document and the odd one, through 64-byte chunks, are their goldens.
	var t *strings.Builder = port.NewText()
	var g []byte = port.TestFile("pdf/tagged/good.json")
	port.AssertEq(emonT, ttAsync(port.TestFile("pdf/tagged/good.pdf"), 64, t), 0, "read")
	port.AssertTextSpan(emonT, t, g, 0, port.BlobLen(g)-1, "good through 64-byte chunks", 1)
	var t2 *strings.Builder = port.NewText()
	var g2 []byte = port.TestFile("pdf/tagged/odd.json")
	port.AssertEq(emonT, ttAsync(port.TestFile("pdf/tagged/odd.pdf"), 512, t2), 0, "read")
	port.AssertTextSpan(emonT, t2, g2, 0, port.BlobLen(g2)-1, "odd through 512-byte chunks", 2)
}
